1	package mevwatch
2	
3	// Regression coverage for the single-block rule comparison behind the
4	// `compare` entry. These tests pin behaviour end to end on the in-package
5	// API: the archived side keeps the version that judged it at archive time,
6	// the candidate side is judged strictly under the version named in the
7	// call (never the currently enabled one), diffs are split per victim
8	// transaction, ordering and evidence are preserved, the query is read
9	// only, and pre-version legacy archives are interpreted as builtin.
10	
11	import (
12		"encoding/json"
13		"os"
14		"path/filepath"
15		"reflect"
16		"sort"
17		"strings"
18		"testing"
19	)
20	
21	const (
22		// archivedVersion is the version under which the fixture block is
23		// archived: sandwich severity 4, displacement severity 1 with
24		// multiplier 3.
25		archivedVersionSpec = `{"id":"archA","rules":{"sandwich":{"enabled":true,"severity":4},"displacement":{"enabled":true,"severity":1,"multiplier":3}}}`
26		// enabledVersion is enabled in the archive afterwards but must never
27		// leak into either side of a comparison. Its judgments are markedly
28		// different: sandwich severity 5, displacement severity 5 with
29		// multiplier 4.
30		enabledVersionSpec = `{"id":"liveB","rules":{"sandwich":{"enabled":true,"severity":5},"displacement":{"enabled":true,"severity":5,"multiplier":4}}}`
31		// candidateVersion is the version named at compare time: sandwich
32		// disabled, displacement severity 4 with the builtin multiplier 2.
33		candidateVersionSpec = `{"id":"candC","rules":{"sandwich":{"enabled":false,"severity":3},"displacement":{"enabled":true,"severity":4,"multiplier":2}}}`
34		// twinVersion carries the builtin parameters under another id, so a
35		// comparison produces identical conclusions and an empty diff.
36		twinVersionSpec = `{"id":"twin","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`
37	)
38	
39	// cmpSwap builds one swap record map; In and Out are fixed because the
40	// detection rules never read them, while every numeric field is explicit.
41	func cmpSwap(tx, pool, trader string, gas int64, index int) map[string]any {
42		return map[string]any{
43			"TxHash": tx, "Pool": pool, "Trader": trader,
44			"In": 1, "Out": 1, "GasPrice": gas, "Index": index,
45		}
46	}
47	
48	func cmpBlockLine(chain, hash string, number int64, swaps ...map[string]any) string {
49		block := map[string]any{
50			"chainId": chain, "blockHash": hash, "blockNumber": number, "swaps": swaps,
51		}
52		raw, err := json.Marshal(block)
53		if err != nil {
54			panic(err)
55		}
56		return string(raw)
57	}
58	
59	// compareFixtureInput covers every diff shape in one archived block:
60	//
61	//	p1 0xa0f/0xa0v/0xa0b  sandwich sev4 under archA -> displacement sev4
62	//	                      under candC (kind change, severity identical);
63	//	p2 0xb0f/0xb0v/0xb0z  displacement sev1 (mult 3) -> sev4 (mult 2),
64	//	                      a severity-only change;
65	//	p3 0xc0f/0xc0v       no conclusion under either version, no diff;
66	//	p4 0xd0f/0xd0v       absent under archA (25 <= 30), displacement
67	//	                      sev4 under candC (25 > 20): added;
68	//	p5 0xe0f/0xe0v/0xe0b sandwich sev4 under archA (15/11 bracket 10),
69	//	                      nothing under candC (sandwich off, 15 <= 20):
70	//	                      removed.
71	func compareFixtureInput() string {
72		lines := []string{
73			cmpBlockLine("1", "0xblk", 100,
74				cmpSwap("0xa0f", "p1", "bot", 90, 0),
75				cmpSwap("0xa0v", "p1", "user", 10, 1),
76				cmpSwap("0xa0b", "p1", "bot", 80, 2),
77				cmpSwap("0xb0f", "p2", "w", 40, 3),
78				cmpSwap("0xb0v", "p2", "u", 10, 4),
79				cmpSwap("0xb0z", "p2", "z", 10, 5),
80				cmpSwap("0xc0f", "p3", "w", 15, 6),
81				cmpSwap("0xc0v", "p3", "u", 10, 7),
82				cmpSwap("0xd0f", "p4", "w", 25, 8),
83				cmpSwap("0xd0v", "p4", "u", 10, 9),
84				cmpSwap("0xe0f", "p5", "bot", 15, 10),
85				cmpSwap("0xe0v", "p5", "user", 10, 11),
86				cmpSwap("0xe0b", "p5", "bot", 11, 12),
87			),
88			// Decoy: same height, different block hash on the same chain.
89			cmpBlockLine("1", "0xother", 100,
90				cmpSwap("0xzz1", "pz", "tz", 999, 0),
91				cmpSwap("0xzz2", "pz", "tz2", 998, 1),
92			),
93			// Decoy: same height and hash on another chain.
94			cmpBlockLine("2", "0xblk", 100,
95				cmpSwap("0xqq1", "pq", "tq", 777, 0),
96				cmpSwap("0xqq2", "pq", "tq2", 776, 1),
97			),
98		}
99		return strings.Join(lines, "\n") + "\n"
100	}
101	
102	// setupCompareArchive writes the fixture to a real (then deleted) input
103	// file, archives it under archA, registers candC and enables liveB. The
104	// returned input path has already been removed, proving compare needs no
105	// source file.
106	func setupCompareArchive(t *testing.T) string {
107		t.Helper()
108		dir := t.TempDir()
109		inputPath := filepath.Join(t.TempDir(), "blocks.jsonl")
110		if err := os.WriteFile(inputPath, []byte(compareFixtureInput()), 0o644); err != nil {
111			t.Fatal(err)
112		}
113		register(t, dir, archivedVersionSpec)
114		register(t, dir, enabledVersionSpec)
115		register(t, dir, candidateVersionSpec)
116		register(t, dir, twinVersionSpec)
117		if reports, err := ReplayFileWithVersion(inputPath, dir, "archA"); err != nil {
118			t.Fatalf("ReplayFileWithVersion: %v", err)
119		} else if len(reports) != 3 {
120			t.Fatalf("got %d reports, want 3", len(reports))
121		}
122		if _, err := EnableVersion(dir, "liveB"); err != nil {
123			t.Fatalf("EnableVersion: %v", err)
124		}
125		if err := os.Remove(inputPath); err != nil {
126			t.Fatal(err)
127		}
128		return dir
129	}
