140	func TestCompareRegressionFullDiff(t *testing.T) {
141		dir := setupCompareArchive(t)
142	
143		result, err := Compare(dir, "1", "0xblk", "candC")
144		if err != nil {
145			t.Fatalf("Compare: %v", err)
146		}
147	
148		// Block identity is exactly the selected chain/block; the same-height
149		// same-chain decoy and the same-hash other-chain decoy never mix in.
150		if result.ChainID != "1" || result.BlockHash != "0xblk" || result.BlockNumber != 100 {
151			t.Fatalf("block identity wrong: %s/%s @%d", result.ChainID, result.BlockHash, result.BlockNumber)
152		}
153	
154		// Each side carries its own full parameters: the archived conclusion
155		// uses archA even though liveB is now enabled, and the candidate side
156		// uses candC rather than the enabled liveB.
157		if !reflect.DeepEqual(result.OriginalVersion, mustRuleVersion(t, archivedVersionSpec)) {
158			t.Fatalf("original version = %+v, want archA", result.OriginalVersion)
159		}
160		if !reflect.DeepEqual(result.ComparedVersion, mustRuleVersion(t, candidateVersionSpec)) {
161			t.Fatalf("compared version = %+v, want candC", result.ComparedVersion)
162		}
163		if result.ComparedVersion.ID == "liveB" ||
164			result.ComparedVersion.Rules.Sandwich.Enabled ||
165			result.ComparedVersion.Rules.Displacement.Multiplier != 2 {
166			t.Fatalf("candidate side leaked the enabled version: %+v", result.ComparedVersion)
167		}
168	
169		// Original findings: severity desc, hash asc within a severity.
170		// p1 and p5 are both sandwiches sev4 (hash asc: 0xa0v before 0xe0v),
171		// the p2 displacement sev1 comes last.
172		wantOrig := []struct {
173			tx       string
174			kind     string
175			severity int
176			evidence int
177		}{
178			{"0xa0v", "sandwich", 4, 3},
179			{"0xe0v", "sandwich", 4, 3},
180			{"0xb0v", "displacement", 1, 2},
181		}
182		if len(result.OriginalFindings) != len(wantOrig) {
183			t.Fatalf("original findings = %+v", result.OriginalFindings)
184		}
185		for i, w := range wantOrig {
186			got := result.OriginalFindings[i]
187			if got.TxHash != w.tx || got.Kind != w.kind || got.Severity != w.severity || len(got.Evidence) != w.evidence {
188				t.Fatalf("original[%d] = %+v, want %+v", i, got, w)
189			}
190		}
191	
192		// Candidate findings: all displacement sev4 under candC (sandwich is
193		// off), hash asc. In particular 0xa0v is a displacement here, so the
194		// enabled liveB (which would still flag it as a sandwich sev5) was
195		// never consulted.
196		wantComp := []struct {
197			tx       string
198			evidence int
199		}{
200			{"0xa0v", 2},
201			{"0xb0v", 2},
202			{"0xd0v", 2},
203		}
204		if len(result.ComparedFindings) != len(wantComp) {
205			t.Fatalf("compared findings = %+v", result.ComparedFindings)
206		}
207		for i, w := range wantComp {
208			got := result.ComparedFindings[i]
209			if got.TxHash != w.tx || got.Kind != "displacement" || got.Severity != 4 || len(got.Evidence) != w.evidence {
210				t.Fatalf("compared[%d] = %+v, want tx %s displacement sev4 with %d evidence", i, got, w.tx, w.evidence)
211			}
212		}
213	
214		// Diffs are per victim transaction with the expected shapes.
215		if len(result.Added) != 1 || result.Added[0].TxHash != "0xd0v" {
216			t.Fatalf("added = %+v", result.Added)
217		}
218		if len(result.Removed) != 1 || result.Removed[0].TxHash != "0xe0v" {
219			t.Fatalf("removed = %+v", result.Removed)
220		}
221		if len(result.Changed) != 2 {
222			t.Fatalf("changed = %+v", result.Changed)
223		}
224		if result.Changed[0].TxHash != "0xa0v" || result.Changed[1].TxHash != "0xb0v" {
225			t.Fatalf("changed not hash-sorted: %+v", result.Changed)
226		}
227	
228		// Sandwich -> displacement for one transaction stays a single change
229		// carrying both conclusions; it must never be split into add+remove.
230		kindChange := result.Changed[0]
231		if kindChange.Original.Kind != "sandwich" || kindChange.Original.Severity != 4 ||
232			len(kindChange.Original.Evidence) != 3 {
233			t.Fatalf("kind change original side wrong: %+v", kindChange.Original)
234		}
235		if kindChange.Compared.Kind != "displacement" || kindChange.Compared.Severity != 4 ||
236			len(kindChange.Compared.Evidence) != 2 {
237			t.Fatalf("kind change compared side wrong: %+v", kindChange.Compared)
238		}
239		// Severity-only change likewise keeps both sides.
240		sevChange := result.Changed[1]
241		if sevChange.Original.Kind != "displacement" || sevChange.Original.Severity != 1 ||
242			sevChange.Compared.Kind != "displacement" || sevChange.Compared.Severity != 4 {
243			t.Fatalf("severity change wrong: %+v", sevChange)
244		}
245	
246		// The victim flagged identically under both versions (none in this
247		// block) would be absent from every diff list; p3's swaps stay only
248		// in the full evidence record.
249	
250		// Full archived swap records survive: all 13, in Index order, with
251		// every original field, including swaps that took no part in any
252		// conclusion (the sandwich backs, 0xb0z and the whole p3 pair).
253		if len(result.Swaps) != 13 {
254			t.Fatalf("swaps = %+v", result.Swaps)
255		}
256		wantSwap := Swap{TxHash: "0xb0z", Pool: "p2", Trader: "z", In: 1, Out: 1, GasPrice: 10, Index: 5}
257		if !reflect.DeepEqual(result.Swaps[5], wantSwap) {
258			t.Fatalf("swap record not preserved: got %+v", result.Swaps[5])
259		}
260		for i, s := range result.Swaps {
261			if s.Index != i {
262				t.Fatalf("swaps not in index order at %d: %+v", i, s)
263			}
264		}
265	
266		// Evidence inside conclusions keeps raw tx/pool/trader/amount/gas/index.
267		ev := result.OriginalFindings[0].Evidence[0]
268		if ev != (Swap{TxHash: "0xa0f", Pool: "p1", Trader: "bot", In: 1, Out: 1, GasPrice: 90, Index: 0}) {
269			t.Fatalf("sandwich evidence damaged: %+v", ev)
270		}
271	}
