273	func TestCompareRegressionDiffListsAreHashSorted(t *testing.T) {
274		dir := t.TempDir()
275		// Archived under builtin: three displacement victims (front gas > 20),
276		// hash order deliberately different from pool/input order.
277		input := strings.Join([]string{
278			cmpBlockLine("1", "0xsort", 9,
