312		if _, err := ReplayWithVersion(strings.NewReader(input), dir2, "m3"); err != nil {
313			t.Fatal(err)
314		}
315		rev, err := Compare(dir2, "1", "0xsort", BuiltinVersionID)
316		if err != nil {
317			t.Fatal(err)
318		}
319		if len(rev.Added) != len(wantRemoved) {
320			t.Fatalf("added = %+v", rev.Added)
321		}
322		for i, tx := range wantRemoved {
323			if rev.Added[i].TxHash != tx {
324				t.Fatalf("added order = %v, want %v", txHashes(rev.Added), wantRemoved)
325			}
326		}
327	}
